mapper.select:
SELECT p.id, p.company_id, p.position_name, p.status, p.created_at, p.updated_at, c.company_name AS companyName FROM org_position p LEFT JOIN org_company c ON c.id = p.company_id WHERE p.status = 1
AND p.company_id = #{companyId}
ORDER BY p.id ASC

mapper.update:
UPDATE org_position
position_name = #{positionName}, status = #{status},
WHERE id = #{id}
